// Independent Google API-shaped data, not generated by the Sheets codec.
export const columns = Object.freeze([
  {name: 'text', type: 'string', nullable: false},
  {name: 'number', type: 'number', nullable: true},
  {name: 'flag', type: 'boolean', nullable: true},
]);
export const expectedRows = [
  {text: '', number: 0, flag: false},
  {text: 'e\u0301\r\n=literal', number: null, flag: null},
  {text: 'e\u0301\r\n=literal', number: null, flag: null},
];
export const blankGridRows = [{}, {values: [{}, {}, {}]}];
export const errorGridRows = [{values: [
  {effectiveValue: {stringValue: 'formula-error'}},
  // The numeric column is nullable: replacing this error with NULL would
  // otherwise be a legal successful row, not an incidental type failure.
  {userEnteredValue: {formulaValue: '=1/0'}, effectiveValue: {
    errorValue: {type: 'DIVIDE_BY_ZERO', message: 'Independent formula error'}}},
]}];
export function sheetsRoutes(state) {
  return [
    {method: 'GET', pathname: '/v4/spreadsheets/book', handle() {
      return {body: {spreadsheetId: 'book', sheets: [
        {properties: {sheetId: 0, sheetType: 'GRID',
          gridProperties: {rowCount: 100, columnCount: 3}}},
        {properties: {sheetId: state.appendSheetId ?? 7, sheetType: 'GRID',
          gridProperties: {rowCount: 100, columnCount: 3}}},
      ]}};
    }},
    {method: 'POST', pathname: '/v4/spreadsheets/book:getByDataFilter', handle(exchange) {
      const request = JSON.parse(exchange.body);
      if (JSON.stringify(request) !== JSON.stringify({dataFilters: [{gridRange: {
        sheetId: 0, startRowIndex: 0, endRowIndex: 4,
        startColumnIndex: 0, endColumnIndex: 3}}], includeGridData: true})) {
        // Object field order is not part of HTTP JSON meaning.
        const grid = request.dataFilters?.[0]?.gridRange;
        if (!request.includeGridData || request.dataFilters.length !== 1 ||
            grid?.sheetId !== 0 || grid.startRowIndex !== 0 || grid.endRowIndex !== 4 ||
            grid.startColumnIndex !== 0 || grid.endColumnIndex !== 3) {
          return {status: 400, body: {}};
        }
      }
      return {body: {spreadsheetId: 'book', sheets: [{properties: {sheetId: 0},
        data: [{rowData: state.gridRows ?? [
          {},
          {values: [{userEnteredValue: {formulaValue: '=\"\"'},
            effectiveValue: {stringValue: ''}},
          {effectiveValue: {numberValue: 0}}, {effectiveValue: {boolValue: false}}]},
          {values: [{effectiveValue: {stringValue: 'e\u0301\r\n=literal'}}]},
          {values: [{effectiveValue: {stringValue: 'e\u0301\r\n=literal'}}]},
        ]}]}]}};
    }},
    {method: 'POST', pathname: '/v4/spreadsheets/book:batchUpdate', handle(exchange) {
      const body = JSON.parse(exchange.body);
      const append = body.requests?.[0]?.appendCells;
      if (body.requests?.length !== 1 || append?.sheetId !== 7 ||
          append.fields !== 'userEnteredValue' || append.rows?.length !== 1 ||
          append.rows[0].values?.some(cell => cell.userEnteredValue?.formulaValue !== undefined)) {
        return {status: 400, body: {}};
      }
      state.appended.push(append.rows[0].values.map(cell => cell.userEnteredValue));
      const observed = state.onAppend?.();
      const reply = {body: {spreadsheetId: 'book', replies: [{}]}};
      return observed === undefined ? reply : Promise.resolve(observed).then(() => reply);
    }},
  ];
}
